 CREATE OR REPLACE FUNCTION public.addprogaddress(insertobj json)                                                                                                                                                                       
  RETURNS uuid                                                                                                                                                                                                                          
  LANGUAGE plpgsql                                                                                                                                                                                                                      
 AS $function$                                                                                                                                                                                                                          
 declare                                                                                                                                                                                                                                
 v_securityuserid character varying;                                                                                                                                                                                                    
 v_applicantid character varying;                                                                                                                                                                                                       
 v_appprofileid character varying;                                                                                                                                                                                                      
 v_randomuuid uuid;                                                                                                                                                                                                                     
                                                                                                                                                                                                                                        
 begin                                                                                                                                                                                                                                  
 v_securityuserid:=insertobj->>'securityuserid';                                                                                                                                                                                        
 v_appprofileid:=insertobj->>'provider_applicant_profile_id';                                                                                                                                                                           
 v_applicantid:=insertobj->>'applicant_id';                                                                                                                                                                                             
                                                                                                                                                                                                                                        
 select gen_random_uuid() into v_randomuuid;                                                                                                                                                                                            
                                                                                                                                                                                                                                        
 INSERT INTO tb_provider_applicant_addresses                                                                                                                                                                                            
 (address_id, adr_street_no,adr_street_nm, create_ts, create_user_id, update_ts, update_user_id, delete_sw,                                                                                                                             
 adr_city_nm, adr_county_cd, adr_state_cd, adr_zip5_no, adr_zip4_no, adr_direction_tx, adr_foreign_tx, adr_foreign_state_tx, adr_country_tx)                                                                                            
 VALUES(v_randomuuid, (insertobj->>'adr_street_no')::int, insertobj->>'adr_street_nm',now(), v_securityuserid, now(), v_securityuserid, 'N'::bpchar, insertobj->>'adr_city_nm', insertobj->>'adr_county_cd',                            
 insertobj->>'adr_state_cd', (insertobj->>'adr_zip5_no')::numeric,(insertobj->>'adr_zip4_no')::numeric, insertobj->>'adr_direction_tx', insertobj->>'adr_foreign_tx', insertobj->>'adr_foreign_state_tx', insertobj->>'adr_country_tx');
                                                                                                                                                                                                                                        
 if length(v_appprofileid)>0                                                                                                                                                                                                            
 then                                                                                                                                                                                                                                   
                                                                                                                                                                                                                                        
 INSERT INTO tb_provider_address_mapping                                                                                                                                                                                                
 (address_mapping_id, object_id, address_id, address_type, create_ts, create_user_id, update_ts, update_user_id, delete_sw)                                                                                                             
 VALUES(gen_random_uuid(),v_appprofileid, v_randomuuid, insertobj->>'address_type', now(), v_securityuserid, now(), v_securityuserid, 'N'::bpchar);                                                                                     
 else                                                                                                                                                                                                                                   
                                                                                                                                                                                                                                        
 INSERT INTO tb_provider_address_mapping                                                                                                                                                                                                
 (address_mapping_id, object_id, address_id, address_type, create_ts, create_user_id, update_ts, update_user_id, delete_sw)                                                                                                             
 VALUES(gen_random_uuid(), v_applicantid, v_randomuuid, insertobj->>'address_type', now(), v_securityuserid, now(), v_securityuserid, 'N'::bpchar);                                                                                     
                                                                                                                                                                                                                                        
 end if;                                                                                                                                                                                                                                
                                                                                                                                                                                                                                        
 return v_randomuuid;                                                                                                                                                                                                                   
                                                                                                                                                                                                                                        
 end                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                        
 $function$                                                                                                                                                                                                                             

